diff --git a/shapes/image/src/ImagePreloader.ts b/shapes/image/src/ImagePreloader.ts
new file mode 100644
index 0000000..d9b5efd
--- /dev/null
+++ b/shapes/image/src/ImagePreloader.ts
@@ -0,0 +1,49 @@
+import type { Engine, IContainerPlugin, IPlugin, RecursivePartial } from "tsparticles-engine";
+import type { IPreloadOptions, PreloadOptions } from "./types";
+import { Preload } from "./Options/Classes/Preload";
+
+export class ImagePreloaderPlugin implements IPlugin {
+    readonly id;
+
+    private readonly _engine;
+
+    constructor(engine: Engine) {
+        this.id = "imagePreloader";
+
+        this._engine = engine;
+    }
+
+    getPlugin(): IContainerPlugin {
+        return {};
+    }
+
+    loadOptions(options: PreloadOptions, source?: RecursivePartial<IPreloadOptions>): void {
+        if (!source || !source.preload) {
+            return;
+        }
+
+        if (!options.preload) {
+            options.preload = [];
+        }
+
+        const preloadOptions = options.preload;
+
+        for (const item of source.preload) {
+            const existing = preloadOptions.find((t) => t.name === item.name || t.src === item.src);
+
+            if (existing) {
+                existing.load(item);
+            } else {
+                const preload = new Preload();
+
+                preload.load(item);
+
+                preloadOptions.push(preload);
+            }
+        }
+    }
+
+    needsPlugin(): boolean {
+        return true;
+    }
+}
diff --git a/shapes/image/src/Options/Classes/Preload.ts b/shapes/image/src/Options/Classes/Preload.ts
new file mode 100644
index 0000000..5b42404
--- /dev/null
+++ b/shapes/image/src/Options/Classes/Preload.ts
@@ -0,0 +1,40 @@
+import type { IOptionLoader, RecursivePartial } from "tsparticles-engine";
+import type { IPreload } from "../Interfaces/IPreload";
+
+export class Preload implements IPreload, IOptionLoader<IPreload> {
+    height?: number;
+    name?: string | undefined;
+    replaceColor?: boolean | undefined;
+    src: string;
+    width?: number;
+
+    constructor() {
+        this.src = "";
+    }
+
+    load(data?: RecursivePartial<IPreload>): void {
+        if (!data) {
+            return;
+        }
+
+        if (data.height !== undefined) {
+            this.height = data.height;
+        }
+
+        if (data.name !== undefined) {
+            this.name = data.name;
+        }
+
+        if (data.replaceColor !== undefined) {
+            this.replaceColor = data.replaceColor;
+        }
+
+        if (data.src !== undefined) {
+            this.src = data.src;
+        }
+
+        if (data.width !== undefined) {
+            this.width = data.width;
+        }
+    }
+}
