+                        "marker_byte" => self.memo[0],
+                    );
+                }
+                Ok(())
+            }
+            StacksEpochId::Epoch2_05 => self.check_epoch_commit_marker(STACKS_EPOCH_2_05_MARKER),
+            StacksEpochId::Epoch21 => self.check_epoch_commit_marker(STACKS_EPOCH_2_1_MARKER),
+        }
+    }
