+/*-----------------------------------------------*\
+    Variables
+\*-----------------------------------------------*/
+@import '../../../_sass_global/variables';
+@import '../../../_sass_global/z-indices';
+@import '../../../_sass_global/interfaces';
+
+/*-----------------------------------------------*\
+    Libs
+\*-----------------------------------------------*/
+@import '~normalize.css';
+
+/*-----------------------------------------------*\
+    Base
+\*-----------------------------------------------*/
+html {
+  height: 100%;
+  box-sizing: border-box;
+}
+
+*, *:before, *:after {
+  box-sizing: inherit;
+}
+
+body {
+  display: flex;
+  justify-content: center;
+  align-items: center;
+  overflow: hidden;
+  height: 100%;
+  margin: 0;
+  padding: 0;
+  color: #333;
+  background-color: rgba(0, 0, 0, 0.4);
+  font-size: 14px;
+  font-family: "Helvetica Neue", Helvetica, Arial, "Hiragino Sans GB", "Hiragino Sans GB W3", "Microsoft YaHei UI", "Microsoft YaHei", "WenQuanYi Micro Hei", sans-serif;
+}
+
+label {
+  display: block;
+  margin-bottom: 5px;
+  font-weight: bold;
+}
+
+input,
+textarea {
+  display: block;
+  resize: vertical;
+  width: 100%;
+  margin-bottom: 15px;
+  padding: 6px 12px;
+  font-size: 14px;
+  line-height: 1.42857;
+  color: #555555;
+  background-color: #fff;
+  background-image: none;
+  border: 1px solid #ccc;
+  border-radius: 4px;
+  box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.075);
+  transition: border-color ease-in-out 0.15s, box-shadow ease-in-out 0.15s;
+
+  &:focus {
+    border-color: #66afe9;
+    outline: 0;
+    box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.075), 0 0 8px rgba(102, 175, 233, 0.6);
+  }
+}
+
+/*-----------------------------------------------*\
+    Components
+\*-----------------------------------------------*/
+.wordEditor-Container {
+  width: 85vw;
+  min-width: 600px;
+  max-width: 1000px;
+  border-radius: 6px;
+  background: #fff;
+  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.5);
+}
+
+.wordEditor-Header {
+  display: flex;
+  border-bottom: 1px solid #e5e5e5;
+}
+
+.wordEditor-Title {
+  margin: 0;
+  font-size: 18px;
+  padding: 15px;
+}
+
+.wordEditor-Note_BtnClose {
+  text-decoration: none;
+  margin-left: auto;
+  padding: 15px;
+  font-size: 21px;
+  font-weight: bold;
+  line-height: 1;
+  border: none;
+  background: transparent;
+  color: #000;
+  text-shadow: 0 1px 0 #fff;
+  opacity: 0.5;
+  cursor: pointer;
+
+  &:hover {
+    outline: none;
+  }
+}
+
+.wordEditor-Main {
+  display: flex;
+  height: 70vh;
+  max-height: 1000px;
+}
+
+.wordEditor-Note {
+  flex: 2;
+  padding: 15px;
+  overflow-x: hidden;
+  overflow-y: scroll;
+}
+
+.wordEditor-Note_SrcFavicon {
+  height: 16px;
+  margin-left: 5px;
+  vertical-align: text-bottom;
+}
+
+.wordEditor-DictPanel {
+  flex: 1;
+  padding: 15px;
+  overflow-x: hidden;
+  overflow-y: scroll;
+}
+
+.wordEditor-WordCards {
+  flex: 1;
+  padding: 15px;
+  overflow-x: hidden;
+  overflow-y: scroll;
+}
+
+.wordEditor-Footer {
+  padding: 15px;
+  text-align: right;
+  border-top: 1px solid #e5e5e5;
+}
+
+%wordEditor-Note_Btn {
+  display: inline-block;
+  margin-bottom: 0;
+  font-weight: normal;
+  text-align: center;
+  vertical-align: middle;
+  touch-action: manipulation;
+  cursor: pointer;
+  background-image: none;
+  border: 1px solid transparent;
+  white-space: nowrap;
+  padding: 6px 12px;
+  font-size: 14px;
+  line-height: 1.42857;
+  border-radius: 4px;
+  user-select: none;
+}
+
+.wordEditor-Note_BtnCancel {
+  @extend %wordEditor-Note_Btn;
+  color: #333;
+  background-color: #fff;
+  border-color: #ccc;
+
+  &:focus {
+    background-color: #e6e6e6;
+    border-color: #8c8c8c;
+  }
+
+  &:hover {
+    outline: 0;
+    background-color: #e6e6e6;
+    border-color: #adadad;
+  }
+
+  &:active {
+    outline: 0;
+    background-color: #e6e6e6;
+    border-color: #8c8c8c;
+    box-shadow: inset 0 3px 5px rgba(0, 0, 0, 0.125);
+  }
+}
+
+.wordEditor-Note_BtnSave {
+  @extend %wordEditor-Note_Btn;
+  margin-left: 10px;
+  color: #fff;
+  background-color: #337ab7;
+  border-color: #2e6da4;
+
+  &:focus {
+    background-color: #286090;
+    border-color: #122b40;
+  }
+
+  &:hover {
+    outline: 0;
+    background-color: #286090;
+    border-color: #204d74;
+  }
+
+  &:active {
+    outline: 0;
+    background-color: #204d74;
+    border-color: #122b40;
+    box-shadow: inset 0 3px 5px rgba(0, 0, 0, 0.125);
+  }
+}
diff --git a/src/content/components/WordEditor/index.tsx b/src/content/components/WordEditor/index.tsx
new file mode 100644
index 0000000..8cbda08
--- /dev/null
+++ b/src/content/components/WordEditor/index.tsx
@@ -0,0 +1,172 @@
+import React, { ButtonHTMLAttributes } from 'react'
+import { translate } from 'react-i18next'
+import { TranslationFunction } from 'i18next'
+import { SelectionInfo } from '@/_helpers/selection'
+import { Word } from '@/background/database'
+
+export interface WordEditorDispatchers {
+  saveToNotebook: (info: SelectionInfo) => void
+  getWordsByText: (text: string) => Promise<Word[]>
+  closeModal: () => void
+}
+
+export interface WordEditorProps extends WordEditorDispatchers {
+  info: SelectionInfo
+}
+
+interface WordEditorState {
+  words: Array<SelectionInfo & { readonly date?: number }>
+  untaintedWords: Array<SelectionInfo & { readonly date?: number }>
+  index: number
+  isFoundOnNotebook: boolean
+}
+
+export class WordEditor extends React.PureComponent<WordEditorProps & { t: TranslationFunction }, WordEditorState> {
+  constructor (props: WordEditorProps & { t: TranslationFunction }) {
+    super(props)
+    this.state = {
+      words: [props.info],
+      untaintedWords: [props.info],
+      index: 0,
+      isFoundOnNotebook: false
+    }
+  }
+
+  mapValueToState = ({ currentTarget }) => {
+    const name = currentTarget.name
+    const newWOrds = [...this.state.words]
+    const i = this.state.index
+    newWOrds[i] = { ...newWOrds[i], [name]: currentTarget.value }
+    this.setState({ words: newWOrds })
+  }
+
+  saveToNotebook = (e: React.MouseEvent<HTMLButtonElement>) => {
+    e.currentTarget.blur()
+    this.state.words.forEach(this.props.saveToNotebook)
+  }
+
+  closeModal = (e: React.MouseEvent<HTMLButtonElement>) => {
+    e.currentTarget.blur()
+    this.props.closeModal()
+  }
+
+  getRelatedWords = () => {
+    const curWord = this.state.words[this.state.index]
+    this.props.getWordsByText(curWord.text)
+      .then(words => {
+        const i = words.findIndex(word =>
+          word.text === curWord.text && word.context === curWord.context
+        )
+        if (i >= 0) {
+          /** @todo */
+        }
+        this.setState({
+          isFoundOnNotebook: i >= 0,
+        })
+      })
+  }
+
+  render () {
+    const {
+      t,
+      saveToNotebook,
+      closeModal,
+    } = this.props
+
+    const info = this.state.words[this.state.index]
+
+    return (
+      <div className='wordEditor-Container'>
+        <header className='wordEditor-Header'>
+          <h1 className='wordEditor-Title'>{t('wordEditorTitle')}</h1>
+          <button type='button'
+            className='wordEditor-Note_BtnClose'
+            onClick={this.closeModal}
+          >×</button>
+        </header>
+        <div className='wordEditor-Main'>
+          <aside className='wordEditor-DictPanel'>
+
+          </aside>
+          <form className='wordEditor-Note'>
+            <label htmlFor='wordEditor-Note_Word'>{t('wordEditorNoteWord')}</label>
+            <input type='text'
+              name='text'
+              id='wordEditor-Note_Word'
+              value={info.text}
+              onChange={this.mapValueToState}
+            />
+            <label htmlFor='wordEditor-Note_Trans'>{t('wordEditorNoteTrans')}</label>
+            <textarea rows={5}
+              name='trans'
+              id='wordEditor-Note_Trans'
+              value={info.trans}
+              onChange={this.mapValueToState}
+            />
+            <label htmlFor='wordEditor-Note_Note'>{t('wordEditorNoteNote')}</label>
+            <textarea rows={5}
+              name='note'
+              id='wordEditor-Note_Note'
+              value={info.note}
+              onChange={this.mapValueToState}
+            />
+            <label htmlFor='wordEditor-Note_Context'>{t('wordEditorNoteContext')}</label>
+            <textarea rows={5}
+              name='context'
+              id='wordEditor-Note_Context'
+              value={info.context}
+              onChange={this.mapValueToState}
+            />
+            <label htmlFor='wordEditor-Note_SrcTitle'>{t('wordEditorNoteSrcTitle')}</label>
+            <input type='text'
+              name='title'
+              id='wordEditor-Note_SrcTitle'
+              value={info.title}
+              onChange={this.mapValueToState}
+            />
+            <label htmlFor='wordEditor-Note_SrcLink'>{t('wordEditorNoteSrcLink')}</label>
+            <input type='text'
+              name='url'
+              id='wordEditor-Note_SrcLink'
+              value={info.url}
+              onChange={this.mapValueToState}
+            />
+            <label htmlFor='wordEditor-Note_SrcFavicon'>
+              {t('wordEditorNoteSrcFavicon')}
+              {info.favicon
+                ? <img
+                    className='wordEditor-Note_SrcFavicon'
+                    src={info.favicon}
+                    alt={t('wordEditorNoteSrcTitle')}
+                  />
+                : null}
+            </label>
+            <input type='text'
+              name='favicon'
+              id='wordEditor-Note_SrcFavicon'
+              value={info.favicon}
+              onChange={this.mapValueToState}
+            />
+          </form>
+          {this.state.words.length > 1 &&
+            <aside className='wordEditor-WordCards'>
+
+            </aside>
+          }
+        </div>
+        <footer className='wordEditor-Footer'>
+          <button type='button'
+            className='wordEditor-Note_BtnCancel'
+            onClick={this.closeModal}
+          >{t('cancel')}</button>
+          <button type='button'
+            className='wordEditor-Note_BtnSave'
+            onClick={this.saveToNotebook}
+          >{t('save')}</button>
+        </footer>
+      </div>
+    )
+  }
+}
+
+export default translate()(WordEditor)
", "diff --git a/test/specs/background/sync-manager/services/ankiconnect.spec.ts b/test/specs/background/sync-manager/services/ankiconnect.spec.ts
