diff --git a/tests/features/unit-of-work/GH4412.test.ts b/tests/features/unit-of-work/GH4412.test.ts
new file mode 100644
index 0000000..e4cda49
--- /dev/null
+++ b/tests/features/unit-of-work/GH4412.test.ts
@@ -0,0 +1,48 @@
+import { Entity, PrimaryKey, Property } from '@mikro-orm/core';
+import { MikroORM } from '@mikro-orm/sqlite';
+import { mockLogger } from '../../helpers';
+
+@Entity()
+export class A {
+
+  @PrimaryKey()
+  id!: number;
+
+  @Property({ nullable: true })
+  createdAt?: Date;
+
+  @Property()
+  name!: string;
+
+}
+
+describe('GH issue 4412', () => {
+  let orm: MikroORM;
+
+  beforeAll(async () => {
+    orm = await MikroORM.init({
+      dbName: ':memory:',
+      entities: [A],
+      forceUndefined: true,
+    });
+
+    await orm.schema.refreshDatabase();
+  });
+
+  afterAll(() => orm.close(true));
+
+  test('update triggered after findOne with forceUndefined true', async () => {
+    orm.em.create(A, {
+      id: 1,
+      name: 'a',
+    });
+    await orm.em.flush();
+
+    const a = await orm.em.findOne(A, { name: 'a' });
+
+    const mock = mockLogger(orm);
+    await orm.em.flush();
+
+    expect(mock).not.toBeCalled();
+  });
+});
