+        }
+
+        // do: stop background task loop
+        shutdown.cancel();
+        join_handle.await.unwrap();
+
+        // no rows should be dropped
+        let batches = run_query(db, "select sum(bar) as n from table_1").await;
+        let expected = vec!["+----+", "| n  |", "+----+", "| 25 |", "+----+"];
+        assert_batches_eq!(expected, &batches);
+    }
