+        let mut out = Vec::with_capacity(self.arr.len());
+        for i in 0..self.arr.len() {
+            if self.arr.is_null(i) {
+                out.push(None)
+            } else {
+                out.push(Some(self.arr.value(i)))
+            }
+        }
+        assert_eq!(out.len(), self.arr.len());
+        out
+    }
