+    fn check_epoch_commit_marker(&self, marker: u8) -> Result<(), op_error> {
+        if self.memo.len() < 1 {
+            debug!(
+                "Invalid block commit";
+                "reason" => "no epoch marker byte given",
+            );
+            return Err(op_error::BlockCommitBadEpoch);
+        }
+        if self.memo[0] < marker {
