+                        "| 22  | b                | 1970-01-01T00:00:00.000000020Z |",
+                        "| 23  | b                | 1970-01-01T00:00:00.000000030Z |",
+                        "+-----+------------------+--------------------------------+",
+                    ],
+                )]),
+            ],
+        }
+        .run()
+        .await;
+    }
