+        let qry = "SELECT block_height FROM block_headers ORDER BY block_height DESC LIMIT 1";
+        query_row(conn, qry, NO_PARAMS)
+            .map(|row_opt: Option<i64>| row_opt.map(|h| h as u64).unwrap_or(0))
+            .map_err(|e| e.into())
