+        conn: &Connection,
+        height: u64,
+    ) -> Result<Vec<StacksHeaderInfo>, Error> {
+        let qry =
+            "SELECT * FROM block_headers WHERE block_height = ?1 ORDER BY burn_header_height DESC";
