diff --git a/tests/issues/GH1704.test.ts b/tests/issues/GH1704.test.ts
new file mode 100644
index 0000000..f634f86
--- /dev/null
+++ b/tests/issues/GH1704.test.ts
@@ -0,0 +1,70 @@
+import { Entity, PrimaryKey, Property, OneToOne, MikroORM, Logger } from '@mikro-orm/core';
+import { SqliteDriver } from '@mikro-orm/sqlite';
+
+@Entity()
+export class Profile {
+
+  @PrimaryKey()
+  id!: number;
+
+  @OneToOne('User', 'profile')
+  user: any;
+
+}
+
+@Entity()
+export class User {
+
+  @PrimaryKey()
+  id!: number;
+
+  @Property()
+  name!: string;
+
+  @OneToOne(() => Profile)
+  profile!: Profile;
+
+}
+
+describe('GH issue 1704', () => {
+
+  let orm: MikroORM<SqliteDriver>;
+
+  beforeAll(async () => {
+    orm = await MikroORM.init({
+      type: 'sqlite',
+      entities: [User, Profile],
+      dbName: ':memory:',
+    });
+    await orm.getSchemaGenerator().createSchema();
+  });
+
+  afterAll(async () => {
+    await orm.close(true);
+  });
+
+  test('loading cached entity with relations', async () => {
+    const user = new User();
+    user.id = 1;
+    user.name = 'Foo';
+    user.profile = new Profile();
+    user.profile.id = 2;
+    await orm.em.fork().persistAndFlush(user);
+
+    const mock = jest.fn();
+    const logger = new Logger(mock, ['query']);
+    Object.assign(orm.config, { logger });
+
+    const getAndFlush = async (expected: number) => {
+      const em = orm.em.fork();
+      await em.findOneOrFail(Profile, 2, { cache: 1000 });
+      await em.findOneOrFail(User, 1);
+      await em.flush();
+      expect(mock.mock.calls).toHaveLength(expected);
+    };
+
+    await getAndFlush(2); // no cache hit
+    await getAndFlush(3); // cache hit, so 2 previous + 1 new query
+  });
+
+});
", "diff --git a/packages/seeder/src/Factory.ts b/packages/seeder/src/Factory.ts
new file mode 100644
index 0000000..3206bf2
--- /dev/null
+++ b/packages/seeder/src/Factory.ts
@@ -0,0 +1,81 @@
+import type { Faker } from '@faker-js/faker';
+import faker from '@faker-js/faker';
+import type { RequiredEntityData, EntityManager } from '@mikro-orm/core';
+
+export abstract class Factory<T> {
+
+  abstract readonly model: { new(): T };
+  private eachFunction?: (entity: T) => void;
+
+  constructor(private readonly em: EntityManager) { }
+
+  protected abstract definition(faker: Faker): Partial<T>;
+
+  private makeEntity(overrideParameters?: Partial<T>): T {
+    const entity = this.em.create(this.model, {
+      ...this.definition(faker),
+      ...overrideParameters,
+    } as unknown as RequiredEntityData<T>);
+
+    if (this.eachFunction) {
+      this.eachFunction(entity);
+    }
+
+    return entity;
+  }
+
+  /**
+   * Make a single entity and persist (not flush)
+   * @param overrideParameters Object specifying what default attributes of the entity factory should be overridden
+   */
+  makeOne(overrideParameters?: Partial<T>): T {
+    const entity = this.makeEntity(overrideParameters);
+    this.em.persist(entity);
+    return entity;
+  }
+
+  /**
+   * Make multiple entities and then persist them (not flush)
+   * @param amount Number of entities that should be generated
+   * @param overrideParameters Object specifying what default attributes of the entity factory should be overridden
+   */
+  make(amount: number, overrideParameters?: Partial<T>): T[] {
+    const entities = [...Array(amount)].map(() => {
+      return this.makeEntity(overrideParameters);
+    });
+    this.em.persist(entities);
+    return entities;
+  }
+
+  /**
+   * Create (and flush) a single entity
+   * @param overrideParameters Object specifying what default attributes of the entity factory should be overridden
+   */
+  async createOne(overrideParameters?: Partial<T>): Promise<T> {
+    const entity = this.makeOne(overrideParameters);
+    await this.em.flush();
+    return entity;
+  }
+
+  /**
+   * Create (and flush) multiple entities
+   * @param amount Number of entities that should be generated
+   * @param overrideParameters Object specifying what default attributes of the entity factory should be overridden
+   */
+  async create(amount: number, overrideParameters?: Partial<T>): Promise<T[]> {
+    const entities = this.make(amount, overrideParameters);
+    await this.em.flush();
+    return entities;
+  }
+
+  /**
+   * Set a function that is applied to each entity before it is returned
+   * In case of `createOne` or `create` it is applied before the entity is persisted
+   * @param eachFunction The function that is applied on every entity
+   */
+  each(eachFunction: (entity: T) => void) {
+    this.eachFunction = eachFunction;
+    return this;
+  }
+
+}
diff --git a/packages/seeder/src/SeedManager.ts b/packages/seeder/src/SeedManager.ts
new file mode 100644
index 0000000..77336be
--- /dev/null
+++ b/packages/seeder/src/SeedManager.ts
@@ -0,0 +1,70 @@
+import type { ISeedManager, EntityManager } from '@mikro-orm/core';
+import { Utils } from '@mikro-orm/core';
+import type { Seeder } from './seeder';
+import { ensureDir, writeFile } from 'fs-extra';
+
+export class SeedManager implements ISeedManager {
+
+  private readonly config = this.em.config;
+  private readonly options = this.config.get('seeder');
+  private readonly absolutePath = Utils.absolutePath(this.options.path, this.config.get('baseDir'));
+
+  constructor(private readonly em: EntityManager) {
+    this.em = this.em.fork();
+  }
+
+  async seed(...seederClasses: { new(): Seeder }[]): Promise<void> {
+    for (const seederClass of seederClasses) {
+      const seeder = new seederClass();
+      await seeder.run(this.em);
+      await this.em.flush();
+      this.em.clear();
+    }
+  }
+
+  async seedString(...seederClasses: string[]): Promise<void> {
+    for (const seederClass of seederClasses) {
+      const seedersPath = Utils.normalizePath(this.absolutePath);
+      const filePath = `${seedersPath}/${this.getFileName(seederClass)}`;
+      const seeder = await import(filePath);
+      await this.seed(seeder[seederClass]);
+    }
+  }
+
+  async createSeeder(seederClass: string): Promise<string> {
+    await this.ensureSeedersDirExists();
+    return this.generate(seederClass);
+  }
+
+  private getFileName(seederClass: string): string {
+    const split = seederClass.split(/(?=[A-Z])/);
+    const parts = split.reduce((previousValue: string[], currentValue: string, index: number) => {
+      if (index === split.length - 1) {
+        return previousValue;
+      }
+      previousValue.push(currentValue.toLowerCase());
+      return previousValue;
+    }, []);
+    return `${parts.join('-')}.seeder.ts`;
+  }
+
+  private async ensureSeedersDirExists() {
+    await ensureDir(Utils.normalizePath(this.absolutePath));
+  }
+
+  private async generate(seederClass: string): Promise<string> {
+    const seedersPath = Utils.normalizePath(this.absolutePath);
+    const filePath = `${seedersPath}/${this.getFileName(seederClass)}`;
+
+    let ret = `import type { EntityManager } from '@mikro-orm/core';\n`;
+    ret += `import { Seeder } from '@mikro-orm/seeder';\n\n`;
+    ret += `export class ${seederClass} extends Seeder {\n\n`;
+    ret += `  async run(em: EntityManager): Promise<void> {}\n\n`;
+    ret += `}\n`;
+
+    await writeFile(filePath, ret);
+
+    return filePath;
+  }
+
+}
diff --git a/packages/seeder/src/Seeder.ts b/packages/seeder/src/Seeder.ts
new file mode 100644
index 0000000..be455a4
--- /dev/null
+++ b/packages/seeder/src/Seeder.ts
@@ -0,0 +1,15 @@
+import type { EntityManager } from '@mikro-orm/core';
+
+export abstract class Seeder {
+
+  abstract run(em: EntityManager): Promise<void>;
+
+  protected call(em: EntityManager, seeders: { new(): Seeder }[]): Promise<void> {
+    return new Promise((resolve, reject) => {
+      Promise.all(seeders.map(s => {
+        return (new s()).run(em.fork());
+      })).then(() => resolve()).catch(reject);
+    });
+  }
+
+}
